mapper.select:
SELECT id.disclosure_id, id.disclosure_number, id.apply_date, id.description, id.approval_status, su.description AS created_by_n, fou.unit_name AS unit_id_n, ( SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ABS.PRODUCT_STATUS' AND v.code_value = id.approval_status ) APPROVAL_STATUS_N FROM ct_abs_information_disclosure id LEFT JOIN sys_user su ON id.created_by = su.user_id LEFT JOIN fnd_org_unit fou ON id.unit_id = fou.unit_id where 1=1
and id.disclosure_id = #{disclosureId}
and id.disclosure_number LIKE CONCAT('%',CONCAT(#{disclosureNumber},'%'))
and id.apply_date = #{applyDate}
and su.description LIKE CONCAT('%',CONCAT(#{createdByN},'%'))
and fou.unit_name LIKE CONCAT('%',CONCAT(#{unitIdN},'%'))
and id.approval_status = #{approvalStatus}
